import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        # Reputation matrix: for each observed agent, track cooperation counts
        # and total interactions observed (as donor or recipient).
        self.reputation = {}  # {agent_id: [coop_count, total_count]}
        # Track own interaction history: for each opponent, last action we took
        self.own_history = {}  # {opponent_id: bool}
        # Track opponent's last action against us
        self.opponent_last = {}  # {opponent_id: bool}
        # Generosity / forgiveness parameter (0..1)
        self.forgiveness = 0.1
        # Baseline trust threshold
        self.trust_threshold = 0.5

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True  # no opponent, cooperate by default

        # If we have no info about opponent, be cooperative initially
        if opponent not in self.reputation:
            return True

        # Compute opponent's observed cooperation rate (as donor and recipient)
        coop, total = self.reputation.get(opponent, [0, 0])
        if total == 0:
            return True

        coop_rate = coop / total

        # If opponent has been cooperative in our past interactions, trust them
        # Also consider their last action against us if we have history
        if opponent in self.opponent_last:
            last_action = self.opponent_last[opponent]
            if last_action:  # they cooperated last time
                return True
            else:
                # If they defected, maybe forgive if overall reputation is good
                if coop_rate >= 0.5:
                    # Forgive with some probability based on forgiveness
                    if random.random() < self.forgiveness:
                        return True
                return False
        else:
            # No direct history, use reputation
            return coop_rate >= self.trust_threshold

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for both donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                # Self-judgment: update own history if we are donor or recipient
                # We need to know who our opponent was in this interaction
                # Determine opponent: if we are donor, opponent is recipient; vice versa
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action
                    opp_action = recipient_action
                else:
                    opponent = donor_id
                    my_action = recipient_action
                    opp_action = donor_action
                self.own_history[opponent] = (my_action == 'cooperate')
                self.opponent_last[opponent] = (opp_action == 'cooperate')
            else:
                # Third-party observation
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                self.reputation[agent_id][1] += 1
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1

import random
import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_history = {}
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.rounds_played = 0
        self.generation = 0
        self.last_opponent = None
        self.my_actions = []
        self.opponent_actions = []
        self.trust = {}
        self.vengefulness = 0.5
        self.generosity = 0.3
        self.adaptation_rate = 0.1
        self.suspicion = 0.2
        self.sliding_window = []
        self.window_size = 30
        self.initial_reputation = 0.5
        self.reputation_learning_rate = 0.2
        self.forgiveness = 0.2
        self.retaliation_memory = {}
        self.coop_streak = 0
        self.defect_streak = 0
        self.overall_coop_rate = 0.5
        self.self_perception = 0.5
        self.opponent_models = {}
        self.pair_history = {}
        self.third_party_trust = {}
        self.time_decay = 0.95
        self.social_learning_rate = 0.1
        self.exploration = 0.05
        self.epsilon = 0.05
        self.my_last_action = None
        self.opponent_last_action = None

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent

        # Initialize state for new opponent
        if opponent not in self.reputation:
            self.reputation[opponent] = self.initial_reputation
        if opponent not in self.cooperation_history:
            self.cooperation_history[opponent] = []
        if opponent not in self.trust:
            self.trust[opponent] = 0.5
        if opponent not in self.retaliation_memory:
            self.retaliation_memory[opponent] = 0
        if opponent not in self.opponent_models:
            self.opponent_models[opponent] = {'coop': 0, 'defect': 0}
        if opponent not in self.pair_history:
            self.pair_history[opponent] = []
        if opponent not in self.third_party_trust:
            self.third_party_trust[opponent] = 0.5

        # Update reputation based on past interactions
        if self.cooperation_history[opponent]:
            recent = self.cooperation_history[opponent][-5:]
            coop_rate = sum(recent) / len(recent)
            self.reputation[opponent] = (1 - self.reputation_learning_rate) * self.reputation[opponent] + self.reputation_learning_rate * coop_rate

        # Adaptive parameters based on overall cooperation
        self.vengefulness = max(0.1, min(0.9, 0.5 + 0.3 * (0.5 - self.overall_coop_rate)))
        self.generosity = max(0.1, min(0.9, 0.3 + 0.2 * self.overall_coop_rate))
        self.suspicion = max(0.05, min(0.5, 0.2 + 0.1 * (0.5 - self.overall_coop_rate)))

        # Check if opponent has been defecting frequently
        recent_opponent_actions = self.cooperation_history[opponent][-10:] if self.cooperation_history[opponent] else []
        if recent_opponent_actions:
            recent_defect_rate = 1 - sum(recent_opponent_actions) / len(recent_opponent_actions)
        else:
            recent_defect_rate = 0.0

        # Retaliation memory: if opponent defected recently, increase suspicion
        if recent_opponent_actions and recent_opponent_actions[-1] == 0:
            self.retaliation_memory[opponent] += 1
        else:
            self.retaliation_memory[opponent] = max(0, self.retaliation_memory[opponent] - 1)

        # Decide based on multiple factors
        base_prob = 0.5
        # Reputation influence
        base_prob += (self.reputation[opponent] - 0.5) * 0.4
        # Trust influence
        base_prob += (self.trust[opponent] - 0.5) * 0.3
        # Vengefulness: retaliate against recent defections
        if self.retaliation_memory[opponent] > 2:
            base_prob -= self.vengefulness * 0.3
        # Generosity: forgive occasional defections
        if recent_defect_rate > 0.5:
            base_prob -= self.suspicion * 0.2
        elif recent_defect_rate > 0:
            base_prob += self.generosity * 0.1
        # Own cooperation streak: if I've been cooperating a lot, maybe be more cautious
        if self.coop_streak > 5:
            base_prob -= 0.1
        # If I've been defecting a lot, try to cooperate more
        if self.defect_streak > 3:
            base_prob += 0.2
        # Third-party trust: if others trust this agent, cooperate more
        base_prob += (self.third_party_trust[opponent] - 0.5) * 0.2
        # Opponent model: if opponent has cooperated most of time, cooperate
        model_total = self.opponent_models[opponent]['coop'] + self.opponent_models[opponent]['defect']
        if model_total > 5:
            model_coop_rate = self.opponent_models[opponent]['coop'] / model_total
            base_prob += (model_coop_rate - 0.5) * 0.3
        # Time decay: recent interactions matter more
        if self.pair_history[opponent]:
            recent_pairs = self.pair_history[opponent][-5:]
            if recent_pairs:
                last_actions = [pair[1] for pair in recent_pairs]
                if last_actions and last_actions[-1] == 0:
                    base_prob -= 0.15

        # Clamp probability
        prob_cooperate = max(0.05, min(0.95, base_prob))

        # Exploration: occasionally randomize
        if random.random() < self.exploration:
            prob_cooperate = 0.5 + random.uniform(-0.2, 0.2)
            prob_cooperate = max(0.05, min(0.95, prob_cooperate))

        # Make decision
        cooperate = random.random() < prob_cooperate
        self.my_last_action = cooperate
        self.opponent_last_action = None  # will be set in observe
        return cooperate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update overall stats
        self.rounds_played += 1

        # Detect self-judgment
        is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
        if is_self:
            # Update own action counts
            if donor_id == self.agent_id:
                my_action = donor_action
                other_id = recipient_id
                other_action = recipient_action
            else:
                my_action = recipient_action
                other_id = donor_id
                other_action = donor_action

            if my_action == 'cooperate':
                self.my_coop_count += 1
                self.coop_streak += 1
                self.defect_streak = 0
            else:
                self.my_defect_count += 1
                self.defect_streak += 1
                self.coop_streak = 0

            # Update overall cooperation rate
            total = self.my_coop_count + self.my_defect_count
            if total > 0:
                self.overall_coop_rate = self.my_coop_count / total

            # Update self-perception
            self.self_perception = self.overall_coop_rate

            # Update interaction history with specific opponent
            if other_id in self.cooperation_history:
                if other_action == 'cooperate':
                    self.cooperation_history[other_id].append(1)
                else:
                    self.cooperation_history[other_id].append(0)

                # Update trust based on opponent's action relative to mine
                if my_action == 'cooperate':
                    if other_action == 'cooperate':
                        self.trust[other_id] = min(1.0, self.trust[other_id] + 0.1)
                    else:
                        self.trust[other_id] = max(0.0, self.trust[other_id] - 0.2)
                else:
                    if other_action == 'cooperate':
                        self.trust[other_id] = min(1.0, self.trust[other_id] + 0.05)
                    else:
                        self.trust[other_id] = max(0.0, self.trust[other_id] - 0.1)

                # Update opponent model
                if other_action == 'cooperate':
                    self.opponent_models[other_id]['coop'] += 1
                else:
                    self.opponent_models[other_id]['defect'] += 1

                # Update pair history
                self.pair_history[other_id].append((my_action == 'cooperate', other_action == 'cooperate'))
                if len(self.pair_history[other_id]) > 50:
                    self.pair_history[other_id].pop(0)

                # Update sliding window for adaptation
                self.sliding_window.append(1 if my_action == 'cooperate' else 0)
                if len(self.sliding_window) > self.window_size:
                    self.sliding_window.pop(0)

                # Update opponent_last_action for possible next round
                self.opponent_last_action = (other_action == 'cooperate')
        else:
            # Third-party observation
            # Update reputation of donor and recipient based on their actions
            if donor_id in self.reputation:
                if donor_action == 'cooperate':
                    self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.05)
                else:
                    self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.1)
            if recipient_id in self.reputation:
                if recipient_action == 'cooperate':
                    self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.05)
                else:
                    self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.1)

            # Update third-party trust for both agents
            if donor_id in self.third_party_trust:
                if donor_action == 'cooperate':
                    self.third_party_trust[donor_id] = min(1.0, self.third_party_trust[donor_id] + 0.03)
                else:
                    self.third_party_trust[donor_id] = max(0.0, self.third_party_trust[donor_id] - 0.06)
            if recipient_id in self.third_party_trust:
                if recipient_action == 'cooperate':
                    self.third_party_trust[recipient_id] = min(1.0, self.third_party_trust[recipient_id] + 0.03)
                else:
                    self.third_party_trust[recipient_id] = max(0.0, self.third_party_trust[recipient_id] - 0.06)

            # Social learning: if both cooperate, increase trust in cooperation norm
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.01)
            elif donor_action == 'defect' or recipient_action == 'defect':
                self.suspicion = min(0.5, self.suspicion + 0.01)

            # Update opponent models for observed agents (helps predict behavior)
            if donor_id in self.opponent_models:
                if donor_action == 'cooperate':
                    self.opponent_models[donor_id]['coop'] += 1
                else:
                    self.opponent_models[donor_id]['defect'] += 1
            if recipient_id in self.opponent_models:
                if recipient_action == 'cooperate':
                    self.opponent_models[recipient_id]['coop'] += 1
                else:
                    self.opponent_models[recipient_id]['defect'] += 1

        # Periodic adaptation of parameters based on sliding window
        if len(self.sliding_window) == self.window_size:
            recent_coop_rate = sum(self.sliding_window) / self.window_size
            if recent_coop_rate < 0.3:
                self.vengefulness = min(0.9, self.vengefulness + 0.02)
                self.suspicion = min(0.5, self.suspicion + 0.01)
            elif recent_coop_rate > 0.7:
                self.generosity = min(0.9, self.generosity + 0.02)
                self.vengefulness = max(0.1, self.vengefulness - 0.01)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation score
        self.coop_count = {}  # agent_id -> number of times cooperated
        self.defect_count = {}  # agent_id -> number of times defected
        self.interaction_count = {}  # agent_id -> total interactions observed
        self.my_opponent = None
        self.rounds_played = 0
        self.my_coop_rate = 0.5  # initial guess
        self.my_total_actions = 0
        self.my_coop_actions = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If we have reputation info, use it; otherwise assume neutral
        if opponent in self.reputation:
            rep = self.reputation[opponent]
            # Cooperate if reputation is positive, defect if negative; if zero, use my own history
            if rep > 0:
                return True
            elif rep < 0:
                return False
            else:
                # If neutral, cooperate with probability equal to my historical cooperation rate
                if self.rounds_played == 0:
                    return True
                return random.random() < self.my_coop_rate
        else:
            # No info: cooperate initially, but if I've been exploited often, be more cautious
            if self.rounds_played == 0:
                return True
            return random.random() < self.my_coop_rate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts for donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            else:
                self.defect_count[agent_id] = self.defect_count.get(agent_id, 0) + 1
            self.interaction_count[agent_id] = self.interaction_count.get(agent_id, 0) + 1

        # Update reputation score: simple heuristic: +1 for cooperate, -1 for defect
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            delta = 1 if action == 'cooperate' else -1
            self.reputation[agent_id] = self.reputation.get(agent_id, 0) + delta

        # If this is my own action, update my personal stats
        if donor_id == self.agent_id:
            self.my_total_actions += 1
            if donor_action == 'cooperate':
                self.my_coop_actions += 1
            self.my_coop_rate = self.my_coop_actions / max(1, self.my_total_actions)
        if recipient_id == self.agent_id:
            self.my_total_actions += 1
            if recipient_action == 'cooperate':
                self.my_coop_actions += 1
            self.my_coop_rate = self.my_coop_actions / max(1, self.my_total_actions)

        # If this is a game involving me, count round
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.rounds_played += 1

