class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation: mapping from agent_id to a score in [-2, 2]
        self.reputation = {}
        # Cooperation history: mapping from agent_id to [my_actions, their_actions]
        self.history = {}
        # Track how many times we've interacted with each agent
        self.interaction_counts = {}
        # Track how many times we've observed each agent cooperating/defecting
        self.observed_coop = {}
        self.observed_defect = {}
        # Strategy parameters
        self.forgiveness = 0.5  # how much we forgive past defections
        self.retaliation = 1.5  # how much we retaliate against defections
        self.trust_threshold = 0.0  # reputation threshold to cooperate

    def _get_reputation(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, 0.0)

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        current = self._get_reputation(agent_id)
        # Clamp reputation to [-2, 2]
        new_score = max(-2.0, min(2.0, current + delta))
        self.reputation[agent_id] = new_score

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If we have no info, cooperate (optimistic start)
        if opponent not in self.history:
            return True

        my_actions, their_actions = self.history[opponent]
        if not my_actions:
            return True

        # Compute opponent's cooperation rate
        coop_rate = sum(their_actions) / len(their_actions)

        # Compute my recent cooperation rate (last 5 interactions)
        recent_my = my_actions[-5:]
        recent_my_rate = sum(recent_my) / len(recent_my) if recent_my else 1.0

        # Reputation influence
        rep = self._get_reputation(opponent)

        # If opponent has a very bad reputation, defect
        if rep < -1.0:
            return False

        # If opponent cooperates often, cooperate
        if coop_rate > 0.7:
            return True

        # If opponent defects often, defect unless we've been cooperating a lot recently
        if coop_rate < 0.3:
            return recent_my_rate > 0.8  # be forgiving if we've been nice

        # Mixed behavior: use reputation and forgiveness
        # If opponent's reputation is positive, cooperate; else defect with some probability based on history
        if rep > self.trust_threshold:
            return True
        else:
            # Tit-for-tat with forgiveness: cooperate if last action was cooperate, else defect with some randomness
            if their_actions and their_actions[-1]:
                return True
            else:
                # Small chance to forgive based on our recent cooperation
                return random.random() < (recent_my_rate * self.forgiveness)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update observed behavior for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.observed_coop[agent_id] = self.observed_coop.get(agent_id, 0) + 1
                # Positive reputation update for cooperation
                self._update_reputation(agent_id, 0.2)
            else:
                self.observed_defect[agent_id] = self.observed_defect.get(agent_id, 0) + 1
                # Negative reputation update for defection
                self._update_reputation(agent_id, -0.2)

        # If we are involved in this interaction, update our history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who is the opponent
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            # Determine our action and their action
            if donor_id == self.agent_id:
                my_action = donor_action == 'cooperate'
                their_action = recipient_action == 'cooperate'
            else:
                my_action = recipient_action == 'cooperate'
                their_action = donor_action == 'cooperate'

            # Update history
            if opponent not in self.history:
                self.history[opponent] = ([], [])
            self.history[opponent][0].append(my_action)
            self.history[opponent][1].append(their_action)

            # Update interaction count
            self.interaction_counts[opponent] = self.interaction_counts.get(opponent, 0) + 1

            # Adjust reputation based on actual outcomes
            if my_action and their_action:
                # Mutual cooperation: positive
                self._update_reputation(opponent, 0.3)
            elif my_action and not their_action:
                # I cooperated, they defected: strong negative
                self._update_reputation(opponent, -self.retaliation * 0.5)
            elif not my_action and their_action:
                # I defected, they cooperated: slight negative (we exploited)
                self._update_reputation(opponent, -0.1)
            else:
                # Mutual defection: mild negative
                self._update_reputation(opponent, -0.2)

        # Third-party observation: update reputation based on observed actions
        else:
