        self.coop_count = 0
        self.defect_count = 0
        self.total_rounds = 0
        self.recent_interactions = {}
        self.opponent_coop_rate = {}
        self.trust = {}
        self.alpha = 0.1
        self.epsilon = 0.05
        self.betrayal_count = {}
        self.coop_after_my_coop = 0
        self.defect_after_my_coop = 0
        self.defection_streak = {}
        self.reputation_threshold = 0.3
        self.reputation_weights = {}
        self.third_party_coop_count = {}
        self.third_party_defect_count = {}
        # New: track recent actions of opponents to detect patterns
        self.opponent_recent_actions = {}
        # New: track opponent's response to my cooperation (reciprocity)
        self.reciprocity = {}

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return True

        self.total_rounds += 1
        self.step_in_gen += 1

        coop_rate = self.opponent_coop_rate.get(opp, 0.5)
        trust = self.trust.get(opp, 0.5)
        betrayal = self.betrayal_count.get(opp, 0)
        streak = self.defection_streak.get(opp, 0)
        opp_rep = self.reputation.get(opp, 0.0)
        # New: use reciprocity information
        recip = self.reciprocity.get(opp, 0.5)

        # If opponent has recently defected after my cooperation, reduce trust more
        if betrayal > 0 and trust < 0.4:
            return random.random() < 0.05

        if streak >= 3:
            return random.random() < 0.1

        # Incorporate reputation and reciprocity into decision
        rep_factor = 1.0 if opp_rep > self.reputation_threshold else 0.5
        recip_factor = 1.0 if recip > 0.3 else 0.7  # Lower cooperation if opponent rarely reciprocates
        rand_val = random.random()
        if coop_rate > 0.4 and trust > 0.3:
            return rand_val < 0.95 * rep_factor * recip_factor
        else:
            return rand_val < 0.15 * rep_factor * recip_factor

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_reward = 1.0 if donor_action == 'cooperate' else -1.0
        self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + self.alpha * (donor_reward - self.reputation.get(donor_id, 0.0))

        recipient_reward = 1.0 if recipient_action == 'cooperate' else -1.0
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + self.alpha * (recipient_reward - self.reputation.get(recipient_id, 0.0))

        # Track third-party cooperation/defection counts for all observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if action == 'cooperate':
                    self.third_party_coop_count[agent_id] = self.third_party_coop_count.get(agent_id, 0) + 1
                else:
                    self.third_party_defect_count[agent_id] = self.third_party_defect_count.get(agent_id, 0) + 1

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp = recipient_id
                opp_action = recipient_action
            else:
                my_action = recipient_action
                opp = donor_id
                opp_action = donor_action

            if opp not in self.recent_interactions:
                self.recent_interactions[opp] = []
            self.recent_interactions[opp].append(my_action)
            if len(self.recent_interactions[opp]) > 10:
                self.recent_interactions[opp].pop(0)

            prev_rate = self.opponent_coop_rate.get(opp, 0.5)
            new_rate = 0.7 * prev_rate + 0.3 * (1.0 if opp_action == 'cooperate' else 0.0)
            self.opponent_coop_rate[opp] = new_rate

            trust_change = 0.1 if opp_action == 'cooperate' else -0.1
            self.trust[opp] = max(0.0, min(1.0, self.trust.get(opp, 0.5) + trust_change))

            if my_action == 'cooperate':
                if opp_action == 'defect':
                    self.betrayal_count[opp] = self.betrayal_count.get(opp, 0) + 1
                else:
                    self.betrayal_count[opp] = self.betrayal_count.get(opp, 0) - 1
                    if self.betrayal_count[opp] < 0:
                        self.betrayal_count[opp] = 0

            if opp_action == 'defect':
                self.defection_streak[opp] = self.defection_streak.get(opp, 0) + 1
            else:
                self.defection_streak[opp] = 0

            # New: track recent actions of opponent to detect patterns (e.g., alternating)
            if opp not in self.opponent_recent_actions:
                self.opponent_recent_actions[opp] = []
            self.opponent_recent_actions[opp].append(1 if opp_action == 'cooperate' else 0)
            if len(self.opponent_recent_actions[opp]) > 5:
                self.opponent_recent_actions[opp].pop(0)

            # New: update reciprocity (how often opponent cooperates after my cooperation)
            if my_action == 'cooperate':
                if opp not in self.reciprocity:
                    self.reciprocity[opp] = []
                self.reciprocity[opp].append(1 if opp_action == 'cooperate' else 0)
                if len(self.reciprocity[opp]) > 10:
                    self.reciprocity[opp].pop(0)
                # Compute average reciprocity
                if self.reciprocity[opp]:
                    self.reciprocity[opp] = sum(self.reciprocity[opp]) / len(self.reciprocity[opp])
                else:
                    self.reciprocity[opp] = 0.5

