        # NEW: Track average reputation of all agents (excluding self) as a baseline
        self.others_avg_rep = self.default_rep

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, self.default_rep)
        my_rep = self.reputation.get(self.agent_id, self.default_rep)
        recent = self.last_interactions.get(opponent, [])
        recent_defections = recent.count('defect')
        if len(recent) > 0 and recent_defections / len(recent) > 0.5:
            threshold = 0.6
        else:
            threshold = 0.4
        # MUTATION: Compare opponent reputation to average of others
        # If opponent is below average, defect more readily; if above, cooperate more
        if my_rep < 0.2:
            return False
        if opp_rep < threshold:
            return False
        # If opponent reputation is significantly above average, cooperate even if slightly below threshold
        if opp_rep < self.others_avg_rep - 0.05:
            return False
        # If opponent reputation is significantly above average, reduce noise defection
        if opp_rep > self.others_avg_rep + 0.15:
            seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
            rng = random.Random(seed)
            if rng.random() < 0.02:
                return False
            return True
        seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
        rng = random.Random(seed)
        if rng.random() < 0.05:
            return False
        return True

    def observe(
        self,
        donor_id: int,
