                # Reset if not exploited
                if recipient_action != 'cooperate' or donor_action != 'defect':
                    self.opp_def_after_coop[donor_id] = 0

        # New: Update streaks for observed opponents (including self when interacting)
        # We'll update streaks for both donor and recipient if they are not self for consistency
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
