        opp_rep = self.reputation.get(opponent, self.default_rep)
        # If my reputation is very low, cooperate to rebuild unless opponent is terrible
        if my_rep < 0.2:
            if opp_rep >= 0.3:
                return True
            else:
                return False
        # If opponent has a long defection streak, defect more aggressively
        streak = self.defection_streaks.get(opponent, 0)
        if streak >= 3:
            return False
        # New: If opponent has recently defected often, be more cautious
        recent_def = self.recent_defections.get(opponent, [])
        if recent_def and sum(recent_def) / len(recent_def) > 0.5:
            return False
        # Use a dynamic threshold with more weight on opponent's recent cooperation
        recent = self.recent_coop_streaks.get(opponent, [])
        recent_coop_rate = sum(recent) / len(recent) if recent else self.default_rep
        # New: Increase threshold if my reputation is low to avoid exploitation
        if my_rep < 0.4:
            threshold = 0.6 - my_rep * 0.2 - (1 - recent_coop_rate) * 0.15
        else:
            threshold = 0.5 - my_rep * 0.15 - (1 - recent_coop_rate) * 0.1
        if opp_rep < threshold:
            return False
        # Add a small chance to defect to avoid predictability
        seed = self.rounds_played * 101 + opponent * 13 + self.agent_id
        rng = random.Random(seed)
        if rng.random() < 0.02:
            return False
        # New: If I have been cooperating a lot and opponent is not too bad, sometimes cooperate to build trust
