    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.total_count = {}
        self.my_history = []
        self.rounds_played = 0
        self.default_rep = 0.5
        self.opponent_coop = {}
        self.opponent_total = {}
        self.recent_coop_streaks = {}
        self.defection_streaks = {}
        self.opponent_reputation = {}
        self.observation_round = 0
        self.last_opponent = None
        self.my_recent_actions = []
        self.recent_defections = {}
        # Track public cooperation history to detect trustworthy third parties
        self.third_party_coop = {}
        self.third_party_total = {}
        # NEW: Track recent actions for all agents including third parties
        self.recent_actions = {}

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        my_rep = self.reputation.get(self.agent_id, self.default_rep)
        opp_rep = self.reputation.get(opponent, self.default_rep)
        # If my reputation is very low, cooperate to rebuild unless opponent is terrible
        if my_rep < 0.2:
            if opp_rep >= 0.3:
                return True
            else:
                return False
        # If opponent has a long defection streak, defect more aggressively
        streak = self.defection_streaks.get(opponent, 0)
        if streak >= 3:
            return False
        # If opponent has recently defected often, be more cautious
        recent_def = self.recent_defections.get(opponent, [])
        if recent_def and sum(recent_def) / len(recent_def) > 0.5:
            return False
        # Use a dynamic threshold with more weight on opponent's recent cooperation
        recent = self.recent_coop_streaks.get(opponent, [])
        recent_coop_rate = sum(recent) / len(recent) if recent else self.default_rep
        # NEW: Use third-party behavior to adjust cooperation threshold
        third_party_rate = self._get_third_party_coop_rate()
        # Increase threshold if third parties are generally uncooperative (risk of being exploited)
        if third_party_rate < 0.5:
            threshold = 0.5 - my_rep * 0.15 - (1 - recent_coop_rate) * 0.1 + 0.1
        else:
            threshold = 0.5 - my_rep * 0.15 - (1 - recent_coop_rate) * 0.1
        if my_rep < 0.4:
            threshold += 0.1
        if opp_rep < threshold:
            return False
        # Add a small chance to defect to avoid predictability
        seed = self.rounds_played * 101 + opponent * 13 + self.agent_id
        rng = random.Random(seed)
        if rng.random() < 0.02:
            return False
        # If I have been cooperating a lot and opponent is not too bad, sometimes cooperate to build trust
        if len(self.my_recent_actions) >= 3 and sum(self.my_recent_actions[-3:]) == 3 and opp_rep >= 0.4:
            return True
        # NEW: If opponent's public reputation is very high, cooperate more often
        if opp_rep >= 0.7:
            return True
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.observation_round += 1
        alpha = 0.25
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
            coop = self.coop_count.get(agent_id, 0)
            new_rep = coop / total
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.reputation[agent_id] = old_rep * (1 - alpha) + new_rep * alpha

            self.opponent_reputation[agent_id] = (self.reputation[agent_id], self.observation_round)

            if agent_id not in self.recent_coop_streaks:
                self.recent_coop_streaks[agent_id] = []
            streak = self.recent_coop_streaks[agent_id]
            streak.append(action == 'cooperate')
            if len(streak) > 5:
                streak.pop(0)

            if action == 'defect':
                self.defection_streaks[agent_id] = self.defection_streaks.get(agent_id, 0) + 1
            else:
                self.defection_streaks[agent_id] = 0

            # Track recent defections for each agent
            if agent_id not in self.recent_defections:
                self.recent_defections[agent_id] = []
            recent_def = self.recent_defections[agent_id]
            recent_def.append(action == 'defect')
            if len(recent_def) > 3:
                recent_def.pop(0)

            # NEW: Track recent actions for all agents
            if agent_id not in self.recent_actions:
                self.recent_actions[agent_id] = []
            recent_acts = self.recent_actions[agent_id]
            recent_acts.append(action == 'cooperate')
            if len(recent_acts) > 3:
                recent_acts.pop(0)

        # Track public cooperation history for all agents, including third parties
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            self.third_party_total[agent_id] = self.third_party_total.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.third_party_coop[agent_id] = self.third_party_coop.get(agent_id, 0) + 1

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.opponent_total:
                    self.opponent_total[agent_id] = 0
                    self.opponent_coop[agent_id] = 0
                self.opponent_total[agent_id] += 1
                if action == 'cooperate':
                    self.opponent_coop[agent_id] += 1

        if donor_id == self.agent_id:
            self.my_history.append((self.rounds_played, recipient_id, donor_action))
            self.rounds_played += 1
            self.my_recent_actions.append(donor_action == 'cooperate')
            if len(self.my_recent_actions) > 5:
                self.my_recent_actions.pop(0)
            if recipient_id not in self.opponent_total:
                self.opponent_total[recipient_id] = 0
                self.opponent_coop[recipient_id] = 0
            self.opponent_total[recipient_id] += 1
            if recipient_action == 'cooperate':
                self.opponent_coop[recipient_id] += 1
        elif recipient_id == self.agent_id:
            self.my_history.append((self.rounds_played, donor_id, recipient_action))
            self.rounds_played += 1
            self.my_recent_actions.append(recipient_action == 'cooperate')
            if len(self.my_recent_actions) > 5:
                self.my_recent_actions.pop(0)
            if donor_id not in self.opponent_total:
                self.opponent_total[donor_id] = 0
                self.opponent_coop[donor_id] = 0
            self.opponent_total[donor_id] += 1
            if donor_action == 'cooperate':
                self.opponent_coop[donor_id] += 1

    def _get_opponent_coop_rate(self, opponent_id: int) -> float:
        total = self.opponent_total.get(opponent_id, 0)
        if total == 0:
            return self.default_rep
        return self.opponent_coop.get(opponent_id, 0) / total

    # NEW: Helper method to compute overall cooperation rate of third parties
    def _get_third_party_coop_rate(self) -> float:
        # Consider agents we've observed but haven't directly played with recently
        third_party_agents = [aid for aid in self.third_party_total if aid != self.agent_id]
        if not third_party_agents:
            return self.default_rep
        total_actions = 0
        total_coop = 0
        for aid in third_party_agents:
            total_actions += self.third_party_total.get(aid, 0)
            total_coop += self.third_party_coop.get(aid, 0)
        if total_actions == 0:
            return self.default_rep
        return total_coop / total_actions

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.total_count = {}
        self.my_history = []
        self.rounds_played = 0
        self.default_rep = 0.5
        self.my_coop_count = 0
        self.my_total_count = 0
        self.opponent_history = {}
        self.my_recent_actions = []
        self.last_interaction_round = {}
        self.exploited_recently = 0
        self.opp_coop_streak = {}
        self.opp_defect_streak = {}
        self.opp_def_after_coop = {}
        self.opp_defections_against_me = {}
        self.opp_history_length = {}
        self.forgiveness_window = 3

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, self.default_rep)
        my_rep = self.reputation.get(self.agent_id, self.default_rep)
        opp_history = self.opponent_history.get(opponent, [])
        if len(opp_history) >= 3:
            recent_coop = sum(1 for a in opp_history[-3:] if a == 'cooperate') / 3
            if recent_coop == 1.0:
                opp_rep = min(1.0, opp_rep + 0.2)
            elif recent_coop <= 0.33:
                opp_rep = max(0.0, opp_rep - 0.2)
        threshold = 0.4
        if my_rep < 0.2:
            return False
        if self.exploited_recently >= 5:
            threshold = 0.5
        if opp_rep < threshold:
            return False
        seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
        rng = random.Random(seed)
        my_coop_rate = self.my_coop_count / max(1, self.my_total_count)
        if my_coop_rate > 0.8:
            if rng.random() < 0.15:
                return False
        recent_with_opp = [a for (_, oid, a) in self.my_history if oid == opponent][-2:]
        if len(recent_with_opp) == 2 and all(a == 'cooperate' for a in recent_with_opp):
            if rng.random() < 0.1:
                return False
        elif rng.random() < 0.05:
            return False
        my_opp_history = [a for (_, oid, a) in self.my_history if oid == opponent]
        if len(my_opp_history) >= 2 and all(a == 'defect' for a in my_opp_history[-2:]):
            return False

        last_round = self.last_interaction_round.get(opponent, -1)
        if self.rounds_played - last_round > 5:
            if rng.random() < 0.3:
                return False

        coop_streak = self.opp_coop_streak.get(opponent, 0)
        defect_streak = self.opp_defect_streak.get(opponent, 0)
        if coop_streak >= 3:
            if rng.random() < 0.02:
                return False
        elif defect_streak >= 2:
            if rng.random() < 0.4:
                return False
        def_after_coop = self.opp_def_after_coop.get(opponent, 0)
        if def_after_coop >= 2:
            if rng.random() < 0.5:
                return False
        def_against_me = self.opp_defections_against_me.get(opponent, 0)
        if def_against_me >= 3:
            if rng.random() < 0.6:
                return False
        hist_len = self.opp_history_length.get(opponent, 0)
        if hist_len < 3:
            if rng.random() < 0.1:
                return False

        # New: forgiveness mechanism - if opponent has cooperated recently after prior defections, reduce punishment
        recent_opp_actions = [a for a in opp_history[-self.forgiveness_window:] if a == 'cooperate']
        if len(recent_opp_actions) >= self.forgiveness_window:
            # Opponent has fully cooperated in the last few interactions, forgive past defections
            if def_against_me > 0 and rng.random() < 0.3:
                # Chance to cooperate despite past defections
                return True
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
            coop = self.coop_count.get(agent_id, 0)
            new_rep = coop / total
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.reputation[agent_id] = old_rep * (1 - alpha) + new_rep * alpha

        if donor_id == self.agent_id and recipient_action == 'defect':
            self.exploited_recently += 1
            self.opp_defections_against_me[recipient_id] = self.opp_defections_against_me.get(recipient_id, 0) + 1
        if self.rounds_played % 10 == 0 and self.exploited_recently > 0:
            self.exploited_recently -= 1

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_action)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = []
            self.opponent_history[recipient_id].append(recipient_action)
            self.opp_history_length[donor_id] = self.opp_history_length.get(donor_id, 0) + 1
            self.opp_history_length[recipient_id] = self.opp_history_length.get(recipient_id, 0) + 1

        if donor_id == self.agent_id:
            self.my_history.append((self.rounds_played, recipient_id, donor_action))
            self.rounds_played += 1
            self.my_total_count += 1
            if donor_action == 'cooperate':
                self.my_coop_count += 1
            self.my_recent_actions.append((recipient_id, donor_action))
            self.last_interaction_round[recipient_id] = self.rounds_played
            if donor_action == 'cooperate' and recipient_action == 'defect':
                self.opp_def_after_coop[recipient_id] = self.opp_def_after_coop.get(recipient_id, 0) + 1
            else:
                if donor_action != 'cooperate' or recipient_action != 'defect':
                    self.opp_def_after_coop[recipient_id] = 0
        elif recipient_id == self.agent_id:
            self.my_history.append((self.rounds_played, donor_id, recipient_action))
            self.rounds_played += 1
            self.my_total_count += 1
            if recipient_action == 'cooperate':
                self.my_coop_count += 1
            self.my_recent_actions.append((donor_id, recipient_action))
            self.last_interaction_round[donor_id] = self.rounds_played
            if recipient_action == 'cooperate' and donor_action == 'defect':
                self.opp_def_after_coop[donor_id] = self.opp_def_after_coop.get(donor_id, 0) + 1
            else:
                if recipient_action != 'cooperate' or donor_action != 'defect':
                    self.opp_def_after_coop[donor_id] = 0

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if action == 'cooperate':
                self.opp_coop_streak[agent_id] = self.opp_coop_streak.get(agent_id, 0) + 1
                self.opp_defect_streak[agent_id] = 0
            else:
                self.opp_defect_streak[agent_id] = self.opp_defect_streak.get(agent_id, 0) + 1
                self.opp_coop_streak[agent_id] = 0

