        # NEW CHANGE: If opponent has exploited us multiple times, defect more aggressively
        exploits = self.exploit_count.get(opponent, 0)
        if exploits >= 2:
            return False
        # If my reputation is very low, cooperate to rebuild unless opponent is terrible
