                    self.opponent_coop[agent_id] = 0
                self.opponent_total[agent_id] += 1
                if action == 'cooperate':
                    self.opponent_coop[agent_id] += 1

        # NEW CHANGE: Track exploitation when we cooperated and opponent defected
        if donor_id == self.agent_id and donor_action == 'cooperate' and recipient_action == 'defect':
            self.exploit_count[recipient_id] = self.exploit_count.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id and recipient_action == 'cooperate' and donor_action == 'defect':
            self.exploit_count[donor_id] = self.exploit_count.get(donor_id, 0) + 1

