                    self.recent_opp_total[agent_id] = len(self.recent_actions_list[agent_id])
                    self.recent_opp_coop[agent_id] = sum(1 for a in self.recent_actions_list[agent_id] if a == 'cooperate')
                # New: Track behavior when opponent has high reputation (rep > 0.7)
                if old_rep > 0.7:
                    self.high_rep_total[agent_id] = self.high_rep_total.get(agent_id, 0) + 1
                    if action == 'cooperate':
                        self.high_rep_coop[agent_id] = self.high_rep_coop.get(agent_id, 0) + 1

        if donor_id == self.agent_id and recipient_action == 'defect':
            self.exploited_recently += 1
            self.opp_defections_against_me[recipient_id] = self.opp_defections_against_me.get(recipient_id, 0) + 1
            self.last_defection_round[recipient_id] = self.rounds_played
        if self.rounds_played % 10 == 0 and self.exploited_recently > 0:
            self.exploited_recently -= 1

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_action)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = []
            self.opponent_history[recipient_id].append(recipient_action)

        if donor_id == self.agent_id:
