                return False
        if recent_total >= 3 and recent_rate < 0.2:
            if rng.random() < 0.3:
                return False
        # New: If opponent has high rep but low cooperation in high-rep situations, defect more
        if high_rep_total >= 3 and high_rep_coop_rate < 0.4:
            if rng.random() < 0.3:
