            threshold = min(threshold, 0.35)
        if self.trust_broken.get(opponent, 0) > 0:
            threshold = max(threshold, 0.6)
        if self.my_betrayal_streak >= 3:
            threshold = max(threshold, 0.65)
        if opp_rep < threshold:
            if random.random() < 0.8:
                return False
        seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
        rng = random.Random(seed)
        my_coop_rate = self.my_coop_count / max(1, self.my_total_count)
        if my_coop_rate > 0.8:
            if rng.random() < 0.15:
                return False
        recent_with_opp = [a for (_, oid, a) in self.my_history if oid == opponent][-2:]
        if len(recent_with_opp) == 2 and all(a == 'cooperate' for a in recent_with_opp):
            if rng.random() < 0.1:
                return False
        elif rng.random() < 0.05:
            return False
        my_opp_history = [a for (_, oid, a) in self.my_history if oid == opponent]
        if len(my_opp_history) >= 2 and all(a == 'defect' for a in my_opp_history[-2:]):
            return False

        last_round = self.last_interaction_round.get(opponent, -1)
        if self.rounds_played - last_round > 5:
            if rng.random() < 0.3:
                return False

        coop_streak = self.opp_coop_streak.get(opponent, 0)
        defect_streak = self.opp_defect_streak.get(opponent, 0)
        if coop_streak >= 3:
            if rng.random() < 0.02:
                return False
        elif defect_streak >= 2:
            if rng.random() < 0.4:
                return False
        def_after_coop = self.opp_def_after_coop.get(opponent, 0)
        if def_after_coop >= 2:
            if rng.random() < 0.5:
                return False
        penalty = self.defection_penalty.get(opponent, 0)
        if penalty >= 3:
            if rng.random() < 0.6:
                return False
        recent_def = self.opp_recent_defections.get(opponent, 0)
        if recent_def >= 3:
            if rng.random() < 0.7:
                return False
        punish = self.punish_count.get(opponent, 0)
        if punish >= 5:
            if rng.random() < 0.5:
                return False
        interaction_freq = self.interaction_count.get(opponent, 0)
        if interaction_freq >= 3:
            threshold = min(threshold, 0.3)
        if self.my_defection_streak >= 3:
            threshold = max(threshold, 0.6)
        if self.my_betrayal_streak >= 3:
            threshold = max(threshold, 0.65)
        if self.forgiveness_count.get(opponent, 0) >= 2:
            threshold = min(threshold, 0.5)

        # New: Use consistency to adjust threshold. If opponent is very consistent (low variance), 
        # we can trust our estimate more, so lower threshold. If inconsistent, raise threshold.
        consistency = self.opp_consistency.get(opponent, 0.5)
        if consistency < 0.2:
            threshold = max(threshold, 0.55)
        elif consistency > 0.8:
            threshold = min(threshold, 0.35)

        if opp_rep >= threshold:
            return True
        return False

    def observe(
        self,
