                self.defection_penalty[recipient_id] = self.defection_penalty.get(recipient_id, 0) + 1
                self.trust_broken[recipient_id] = self.trust_broken.get(recipient_id, 0) + 1
                self.my_betrayal_streak += 1
            else:
                if donor_action != 'cooperate' or recipient_action != 'defect':
                    self.opp_def_after_coop[recipient_id] = 0
                if not (donor_action == 'cooperate' and recipient_action == 'defect'):
                    self.my_betrayal_streak = 0
            if donor_action == 'defect':
