            self.last_interaction_round[donor_id] = self.rounds_played
            self.interaction_count[donor_id] = self.interaction_count.get(donor_id, 0) + 1
            if recipient_action == 'cooperate' and donor_action == 'defect':
                self.opp_def_after_coop[donor_id] = self.opp_def_after_coop.get(donor_id, 0) + 1
                self.defection_penalty[donor_id] = self.defection_penalty.get(donor_id, 0) + 1
                self.trust_broken[donor_id] = self.trust_broken.get(donor_id, 0) + 1
                self.my_betrayal_streak += 1
            else:
                if recipient_action != 'cooperate' or donor_action != 'defect':
                    self.opp_def_after_coop[donor_id] = 0
                if not (recipient_action == 'cooperate' and donor_action == 'defect'):
                    self.my_betrayal_streak = 0
            if recipient_action == 'defect':
                self.my_defection_streak += 1
            else:
                self.my_defection_streak = 0

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if action == 'cooperate':
                self.opp_coop_streak[agent_id] = self.opp_coop_streak.get(agent_id, 0) + 1
                self.opp_defect_streak[agent_id] = 0
            else:
                self.opp_defect_streak[agent_id] = self.opp_defect_streak.get(agent_id, 0) + 1
