            if action == 'defect':
                self.opp_recent_defections[agent_id] = self.opp_recent_defections.get(agent_id, 0) + 1
            else:
                self.opp_recent_defections[agent_id] = 0

        if donor_id == self.agent_id and donor_action == 'defect' and recipient_id != self.agent_id:
            self.punish_count[recipient_id] = self.punish_count.get(recipient_id, 0) + 1
        if recipient_id == self.agent_id and recipient_action == 'defect' and donor_id != self.agent_id:
            self.punish_count[donor_id] = self.punish_count.get(donor_id, 0) + 1

        if donor_id == self.agent_id and donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.cooperation_count_with[recipient_id] = self.cooperation_count_with.get(recipient_id, 0) + 1
        elif donor_id != self.agent_id and recipient_id == self.agent_id and recipient_action == 'cooperate' and donor_action == 'cooperate':
            self.cooperation_count_with[donor_id] = self.cooperation_count_with.get(donor_id, 0) + 1

        if donor_id == self.agent_id and donor_action == 'cooperate':
            if self.trust_broken.get(recipient_id, 0) > 0:
                self.forgiveness_count[recipient_id] = self.forgiveness_count.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id and recipient_action == 'cooperate':
            if self.trust_broken.get(donor_id, 0) > 0:
                self.forgiveness_count[donor_id] = self.forgiveness_count.get(donor_id, 0) + 1

        # New: Track opponent's action sequence and compute consistency (fraction of same as majority)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if agent_id not in self.opp_action_sequence:
                self.opp_action_sequence[agent_id] = []
            self.opp_action_sequence[agent_id].append(action)
            seq = self.opp_action_sequence[agent_id]
            if len(seq) > 0:
                coop_count = sum(1 for a in seq if a == 'cooperate')
                majority = max(coop_count, len(seq) - coop_count)
                self.opp_consistency[agent_id] = majority / len(seq)

