                self.opp_last_action[agent_id] = action
                # New: Track donor-specific stats for the donor
                if agent_id == donor_id:
                    self.opp_donor_total_count[agent_id] = self.opp_donor_total_count.get(agent_id, 0) + 1
                    if action == 'cooperate':
                        self.opp_donor_coop_count[agent_id] = self.opp_donor_coop_count.get(agent_id, 0) + 1
                # New: Track recipient-specific defection stats
                if agent_id == recipient_id:
