            self.interaction_count[recipient_id] = self.interaction_count.get(recipient_id, 0) + 1
            if donor_action == 'cooperate' and recipient_action == 'defect':
                self.opp_def_after_coop[recipient_id] = self.opp_def_after_coop.get(recipient_id, 0) + 1
                self.defection_penalty[recipient_id] = self.defection_penalty.get(recipient_id, 0) + 1
