                self.reciprocal_coop_count[donor_id] = self.reciprocal_coop_count.get(donor_id, 0) + 1
            else:
                self.reciprocal_def_count[donor_id] = self.reciprocal_def_count.get(donor_id, 0) + 1

        # New: Update long-term cooperation ratio for the donor
        if donor_id != self.agent_id:
            total_interactions = self.total_count.get(donor_id, 0)
            coop_interactions = self.coop_count.get(donor_id, 0)
            if total_interactions > 0:
                self.opp_long_term_coop[donor_id] = coop_interactions / total_interactions

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if action == 'cooperate':
                self.opp_coop_streak[agent_id] = self.opp_coop_streak.get(agent_id, 0) + 1
                self.opp_defect_streak[agent_id] = 0
