                self.opp_coop_streak[agent_id] = 0
        if recipient_id == self.agent_id and donor_id != self.agent_id:
            self.opp_last_action_before_my_turn[donor_id] = donor_action

        if donor_id == self.agent_id:
            self.my_recent_actions_list.append(donor_action)
        elif recipient_id == self.agent_id:
            self.my_recent_actions_list.append(recipient_action)
        if len(self.my_recent_actions_list) > 10:
