        if opp_recip_defect_rate < 0.1 and rng.random() < 0.05:
            return True
        # New: If opponent's recent cooperation rate with me is very high, cooperate more
        recent_rate_with_me = self.recent_opp_rate_with_me.get(opponent, 0.5)
