                    self.opp_recent_coop_obs[agent_id] = 0
                self.opp_recent_total_obs[agent_id] += 1
                if action == 'cooperate':
                    self.opp_recent_coop_obs[agent_id] += 1
                if self.opp_recent_total_obs[agent_id] > 10:
                    self.opp_recent_total_obs[agent_id] = 10
                    self.opp_recent_coop_obs[agent_id] = int(self.opp_recent_coop_obs[agent_id] * 0.9)
                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    if (last == 'cooperate') != (action == 'cooperate'):
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 0.0
                    else:
