        self.my_donor_total_count = 0
        self.opp_recipient_defect_count = {}
        self.opp_recipient_total_count = {}
        self.opp_coop_with_me = {}
        self.opp_total_with_me = {}
        self.opp_recent_coop_with_me = {}
        self.opp_response_consistency = {}
        self.opp_response_last = {}

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, self.default_rep)
        my_rep = self.reputation.get(self.agent_id, self.default_rep)
        opp_history = self.opponent_history.get(opponent, [])
        if len(opp_history) >= 3:
            recent_coop = sum(1 for a in opp_history[-3:] if a == 'cooperate') / 3
            if recent_coop == 1.0:
                opp_rep = min(1.0, opp_rep + 0.2)
            elif recent_coop <= 0.33:
                opp_rep = max(0.0, opp_rep - 0.2)
        threshold = 0.4
        if my_rep < 0.2:
            return False
        if self.exploited_recently >= 5:
            threshold = 0.5
        trend = self.rep_change.get(opponent, 0)
        if trend < -0.1:
            threshold = 0.6
        elif trend > 0.1:
            threshold = 0.35
        opp_rate = self.opp_coop_rate.get(opponent, 0.5)
        if opp_rate < 0.3:
            threshold = max(threshold, 0.55)
        elif opp_rate > 0.7:
            threshold = min(threshold, 0.3)
        opp_total = self.opp_total_obs.get(opponent, 0)
        opp_coop = self.opp_coop_obs.get(opponent, 0)
        if opp_total >= 10:
            observed_rate = opp_coop / opp_total
            if observed_rate < 0.25:
                threshold = max(threshold, 0.6)
            elif observed_rate > 0.75:
                threshold = min(threshold, 0.35)
        if self.others_total_with_me >= 5:
            others_rate = self.others_coop_with_me / self.others_total_with_me
            my_rate = self.my_coop_count / max(1, self.my_total_count)
            if others_rate < my_rate - 0.2:
                threshold = max(threshold, 0.55)
        consistency = self.opp_behavior_consistency.get(opponent, 1.0)
        if consistency < 0.4:
            threshold = max(threshold, 0.5)
        last_action_before = self.opp_last_action_before_my_turn.get(opponent, None)
        if last_action_before == 'defect':
            threshold = max(threshold, 0.55)
        recent_coop_with_me = self.recent_opp_coop_with_me.get(opponent, [])
        if len(recent_coop_with_me) >= 3:
            recent_rate = sum(1 for a in recent_coop_with_me if a == 'cooperate') / len(recent_coop_with_me)
            if recent_rate < 0.3:
                threshold = max(threshold, 0.6)
            elif recent_rate > 0.7:
                threshold = min(threshold, 0.3)
        last_obs = self.last_obs_round.get(opponent, -1)
        if self.obs_round - last_obs > 10:
            threshold = max(threshold, 0.5)
        opp_donor_total = self.opp_donor_total_count.get(opponent, 0)
        if opp_donor_total >= 5:
            opp_donor_rate = self.opp_donor_coop_count.get(opponent, 0) / opp_donor_total
            if opp_donor_rate < 0.25:
                threshold = max(threshold, 0.65)
            elif opp_donor_rate > 0.75:
                threshold = min(threshold, 0.3)
        opp_recip_total = self.opp_recipient_total_count.get(opponent, 0)
        if opp_recip_total >= 5:
            opp_recip_defect_rate = self.opp_recipient_defect_count.get(opponent, 0) / opp_recip_total
            if opp_recip_defect_rate > 0.5:
                threshold = max(threshold, 0.6)
            elif opp_recip_defect_rate < 0.2:
                threshold = min(threshold, 0.35)
        opp_total_with_me = self.opp_total_with_me.get(opponent, 0)
        if opp_total_with_me >= 3:
            opp_coop_with_me_rate = self.opp_coop_with_me.get(opponent, 0) / opp_total_with_me
            if opp_coop_with_me_rate < 0.3:
                threshold = max(threshold, 0.6)
            elif opp_coop_with_me_rate > 0.7:
                threshold = min(threshold, 0.3)
        opp_recent_coop = self.opp_recent_coop_with_me.get(opponent, [])
        if len(opp_recent_coop) >= 3:
            recent_rate = sum(1 for a in opp_recent_coop if a == 'cooperate') / len(opp_recent_coop)
            if recent_rate < 0.3:
                threshold = max(threshold, 0.6)
            elif recent_rate > 0.7:
                threshold = min(threshold, 0.3)
        # New: response consistency - if opponent's actions are unpredictable relative to my actions, be cautious
        resp_consistency = self.opp_response_consistency.get(opponent, 1.0)
        if resp_consistency < 0.3:
            threshold = max(threshold, 0.55)
        if opp_rep < threshold:
            return False
        seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
        rng = random.Random(seed)
        my_coop_rate = self.my_coop_count / max(1, self.my_total_count)
        if my_coop_rate > 0.8:
            if rng.random() < 0.15:
                return False
        recent_with_opp = [a for (_, oid, a) in self.my_history if oid == opponent][-2:]
        if len(recent_with_opp) == 2 and all(a == 'cooperate' for a in recent_with_opp):
            if rng.random() < 0.1:
                return False
        elif rng.random() < 0.05:
            return False
        my_opp_history = [a for (_, oid, a) in self.my_history if oid == opponent]
        if len(my_opp_history) >= 2 and all(a == 'defect' for a in my_opp_history[-2:]):
            return False

        last_round = self.last_interaction_round.get(opponent, -1)
        if self.rounds_played - last_round > 5:
            if rng.random() < 0.3:
                return False

        coop_streak = self.opp_coop_streak.get(opponent, 0)
        defect_streak = self.opp_defect_streak.get(opponent, 0)
        if coop_streak >= 3:
            if rng.random() < 0.02:
                return False
        elif defect_streak >= 2:
            if rng.random() < 0.4:
                return False
        def_after_coop = self.opp_def_after_coop.get(opponent, 0)
        if def_after_coop >= 2:
            if rng.random() < 0.5:
                return False
        if self.self_reputation_estimate > 0.7:
            if rng.random() < 0.05:
                return True
        my_donor_rate = self.my_donor_coop_count / max(1, self.my_donor_total_count)
        if my_donor_rate > 0.8 and rng.random() < 0.1:
            return True
        opp_recip_defect_rate = self.opp_recipient_defect_count.get(opponent, 0) / max(1, self.opp_recipient_total_count.get(opponent, 0))
        if opp_recip_defect_rate < 0.1 and rng.random() < 0.05:
            return True
        opp_total_with_me = self.opp_total_with_me.get(opponent, 0)
        if opp_total_with_me >= 3:
            opp_coop_with_me_rate = self.opp_coop_with_me.get(opponent, 0) / opp_total_with_me
            if opp_coop_with_me_rate > 0.8 and rng.random() < 0.1:
                return True
        # New: if opponent's response consistency is high and they cooperate with me, be more cooperative
        if resp_consistency > 0.7 and opp_coop_with_me_rate > 0.6 and rng.random() < 0.1:
            return True
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.obs_round += 1
        for agent_id in [donor_id, recipient_id]:
            if agent_id != self.agent_id:
                self.last_obs_round[agent_id] = self.obs_round
        alpha = 0.1
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
            coop = self.coop_count.get(agent_id, 0)
            new_rep = coop / total
            self.reputation[agent_id] = old_rep * (1 - alpha) + new_rep * alpha
            if agent_id in self.rep_change:
                self.rep_change[agent_id] = self.rep_change[agent_id] * 0.9 + (self.reputation[agent_id] - old_rep) * 0.1
            else:
                self.rep_change[agent_id] = self.reputation[agent_id] - old_rep
            if agent_id != self.agent_id:
                if agent_id not in self.opp_coop_rate:
                    self.opp_coop_rate[agent_id] = 0.5
                total_obs = self.total_count[agent_id]
                coop_obs = self.coop_count[agent_id]
                self.opp_coop_rate[agent_id] = coop_obs / max(1, total_obs)
                self.opp_total_obs[agent_id] = self.opp_total_obs.get(agent_id, 0) + 1
                if action == 'cooperate':
                    self.opp_coop_obs[agent_id] = self.opp_coop_obs.get(agent_id, 0) + 1
                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    if (last == 'cooperate') != (action == 'cooperate'):
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 0.0
                    else:
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 1.0
                else:
                    self.opp_behavior_consistency[agent_id] = 1.0
                self.opp_last_action[agent_id] = action
                if agent_id == donor_id:
                    self.opp_donor_total_count[agent_id] = self.opp_donor_total_count.get(agent_id, 0) + 1
                    if action == 'cooperate':
                        self.opp_donor_coop_count[agent_id] = self.opp_donor_coop_count.get(agent_id, 0) + 1
                if agent_id == recipient_id:
                    self.opp_recipient_total_count[agent_id] = self.opp_recipient_total_count.get(agent_id, 0) + 1
                    if action == 'defect':
                        self.opp_recipient_defect_count[agent_id] = self.opp_recipient_defect_count.get(agent_id, 0) + 1
                # Track interactions with me
                if recipient_id == self.agent_id:
                    self.opp_total_with_me[donor_id] = self.opp_total_with_me.get(donor_id, 0) + 1
                    if donor_action == 'cooperate':
                        self.opp_coop_with_me[donor_id] = self.opp_coop_with_me.get(donor_id, 0) + 1
                    self.opp_recent_coop_with_me.setdefault(donor_id, []).append(donor_action)
                    if len(self.opp_recent_coop_with_me[donor_id]) > 3:
                        self.opp_recent_coop_with_me[donor_id].pop(0)
                    # New: track response consistency - how similar opponent's action is to mine in same interaction
                    if donor_id != self.agent_id:
                        if donor_id in self.opp_response_last:
                            prev = self.opp_response_last[donor_id]
                            if (prev == 'cooperate') != (donor_action == 'cooperate'):
                                self.opp_response_consistency[donor_id] = self.opp_response_consistency.get(donor_id, 1.0) * 0.9 + 0.0
                            else:
                                self.opp_response_consistency[donor_id] = self.opp_response_consistency.get(donor_id, 1.0) * 0.9 + 1.0
                        else:
                            self.opp_response_consistency[donor_id] = 1.0
                        self.opp_response_last[donor_id] = donor_action

        if donor_id == self.agent_id and recipient_action == 'defect':
            self.exploited_recently += 1
        if self.rounds_played % 10 == 0 and self.exploited_recently > 0:
            self.exploited_recently -= 1

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_action)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = []
            self.opponent_history[recipient_id].append(recipient_action)

        if donor_id == self.agent_id:
            self.my_history.append((self.rounds_played, recipient_id, donor_action))
            self.rounds_played += 1
            self.my_total_count += 1
            self.my_donor_total_count += 1
            if donor_action == 'cooperate':
                self.my_coop_count += 1
                self.my_donor_coop_count += 1
            self.my_recent_actions.append((recipient_id, donor_action))
            self.last_interaction_round[recipient_id] = self.rounds_played

