        if opp_total >= 10:
            observed_rate = opp_coop / opp_total
            if observed_rate < 0.25:
                threshold = max(threshold, 0.6)
            elif observed_rate > 0.75:
                threshold = min(threshold, 0.35)
        if self.others_total_with_me >= 5:
            others_rate = self.others_coop_with_me / self.others_total_with_me
            my_rate = self.my_coop_count / max(1, self.my_total_count)
