                defect_after = self.opp_coop_after_my_coop.get(opponent, 0)
            total_after = coop_after + defect_after
            if total_after >= 2:
                # If opponent often cooperates after our cooperation, be more cooperative
                if my_last == 'cooperate' and coop_after / total_after > 0.7:
                    if rng.random() < 0.05:  # small chance to defect to test
                        return False
                # If opponent often defects after our cooperation, be more cautious
                if my_last == 'cooperate' and defect_after / total_after > 0.7:
                    if rng.random() < 0.5:
                        return False
                # If opponent often cooperates after our defection, consider cooperating occasionally
                if my_last == 'defect' and coop_after / total_after > 0.5:
                    if rng.random() < 0.1:  # small chance to cooperate to test
                        return True
        return True

