        if reciprocal_coop > 0 and reciprocal_def == 0:
            if rng.random() < 0.1:  # small chance to defect even if they cooperated
                return False
        elif reciprocal_def > 0 and reciprocal_coop == 0:
            if rng.random() < 0.6:  # higher chance to defect if they defected
                return False
        # New: Conditional cooperation based on opponent's response to our cooperation
        coop_after_def = self.coop_after_def_count.get(opponent, 0)
        def_after_def = self.def_after_def_count.get(opponent, 0)
        if def_after_def > coop_after_def:
