        if reciprocal_def > 0 and recent_rate > 0.8 and reciprocal_def <= 2:
            if rng.random() < 0.1:
                return False
        # New change: If we have punished this opponent many times and they are now cooperating, 
        # reduce the probability of defection to encourage reconciliation
        punishments = self.punishment_history.get(opponent, 0)
        if punishments >= 3 and recent_rate > 0.8:
            if rng.random() < 0.05:
