    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
            coop = self.coop_count.get(agent_id, 0)
            new_rep = coop / total
            self.reputation[agent_id] = old_rep * (1 - alpha) + new_rep * alpha
            if agent_id in self.rep_change:
                self.rep_change[agent_id] = self.rep_change[agent_id] * 0.9 + (self.reputation[agent_id] - old_rep) * 0.1
            else:
                self.rep_change[agent_id] = self.reputation[agent_id] - old_rep
            if agent_id != self.agent_id:
                if agent_id not in self.opp_coop_rate:
                    self.opp_coop_rate[agent_id] = 0.5
                total_obs = self.total_count[agent_id]
                coop_obs = self.coop_count[agent_id]
                self.opp_coop_rate[agent_id] = coop_obs / max(1, total_obs)
