        if len(self.my_recent_actions_list) >= 5:
            my_recent_coop = sum(1 for a in self.my_recent_actions_list if a == 'cooperate') / len(self.my_recent_actions_list)
            self.self_reputation_estimate = self.self_reputation_estimate * 0.9 + my_recent_coop * 0.1
        else:
            self.self_reputation_estimate = 0.5

