        if self.rounds_played - last_round > 5:
            if rng.random() < 0.3:
                return False

        coop_streak = self.opp_coop_streak.get(opponent, 0)
        defect_streak = self.opp_defect_streak.get(opponent, 0)
        if coop_streak >= 3:
            if rng.random() < 0.02:
                return False
        elif defect_streak >= 2:
            if rng.random() < 0.4:
                return False
        def_after_coop = self.opp_def_after_coop.get(opponent, 0)
        if def_after_coop >= 2:
            if rng.random() < 0.5:
                return False
        reciprocal_coop = self.reciprocal_coop_count.get(opponent, 0)
        reciprocal_def = self.reciprocal_def_count.get(opponent, 0)
        if reciprocal_coop > 0 and reciprocal_def == 0:
            if rng.random() < 0.1:
                return False
        elif reciprocal_def > 0 and reciprocal_coop == 0:
            if rng.random() < 0.6:
                return False
        # New: Forgiveness based on recent cooperation rate with this opponent
        recent_rate = self.recent_opp_coop_rate.get(opponent, 0.5)
        if reciprocal_def > reciprocal_coop and recent_rate > 0.7:
            if rng.random() < 0.15:
                return False
        # New: More forgiving if long-term reputation is high
        if long_rep > 0.7 and reciprocal_def > reciprocal_coop:
            if rng.random() < 0.2:
                return False
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
