        if cond_def_rate is not None and cond_def_rate > 0.6:
            threshold = max(threshold, 0.7)
        elif cond_def_rate is not None and cond_def_rate > 0.4:
            threshold = max(threshold, 0.6)
        # Additional mutation: if opponent defects after my defection consistently, lower threshold slightly
        cond_def_after_def = None
        if self.opp_def_after_my_defect_total.get(opponent, 0) >= 2:
            cond_def_after_def = self.opp_def_after_my_defect_count.get(opponent, 0) / self.opp_def_after_my_defect_total[opponent]
        if cond_def_after_def is not None and cond_def_after_def > 0.8:
            threshold = min(threshold, 0.5)
        if opp_rep < threshold:
            return False
