        my_coop_rate = self.my_coop_count / max(1, self.my_total_count)
        if my_coop_rate > 0.8:
            if rng.random() < 0.15:
                return False
        recent_with_opp = [a for (_, oid, a) in self.my_history if oid == opponent][-2:]
        if len(recent_with_opp) == 2 and all(a == 'cooperate' for a in recent_with_opp):
            if rng.random() < 0.1:
                return False
        elif rng.random() < 0.05:
            return False
        my_opp_history = [a for (_, oid, a) in self.my_history if oid == opponent]
        if len(my_opp_history) >= 2 and all(a == 'defect' for a in my_opp_history[-2:]):
            return False

        last_round = self.last_interaction_round.get(opponent, -1)
        if self.rounds_played - last_round > 5:
            if rng.random() < 0.3:
                return False

        coop_streak = self.opp_coop_streak.get(opponent, 0)
        defect_streak = self.opp_defect_streak.get(opponent, 0)
        if coop_streak >= 3:
            if rng.random() < 0.02:
                return False
        elif defect_streak >= 2:
            if rng.random() < 0.4:
                return False
        def_after_coop = self.opp_def_after_coop.get(opponent, 0)
        if def_after_coop >= 2:
            if rng.random() < 0.5:
                return False
        reciprocal_coop = self.reciprocal_coop_count.get(opponent, 0)
        reciprocal_def = self.reciprocal_def_count.get(opponent, 0)
        if reciprocal_coop > 0 and reciprocal_def == 0:
            if rng.random() < 0.1:
                return False
        elif reciprocal_def > 0 and reciprocal_coop == 0:
            if rng.random() < 0.6:
                return False

        my_last = self.my_last_action_to_opp.get(opponent, None)
        if my_last is not None:
            if my_last == 'cooperate':
                coop_after = self.opp_coop_after_my_coop_opp.get(opponent, 0)
                defect_after = self.opp_def_after_my_coop_opp.get(opponent, 0)
            else:
                coop_after = self.opp_coop_after_my_defect_opp.get(opponent, 0)
                defect_after = self.opp_def_after_my_defect_opp.get(opponent, 0)
            total_after = coop_after + defect_after
            if total_after >= 2:
                if my_last == 'cooperate' and coop_after / total_after > 0.7:
                    if rng.random() < 0.05:
                        return False
                if my_last == 'cooperate' and defect_after / total_after > 0.7:
                    if rng.random() < 0.5:
                        return False
                if my_last == 'defect' and coop_after / total_after > 0.5:
                    if rng.random() < 0.1:
                        return True
                if my_last == 'defect' and defect_after / total_after > 0.7:
                    if rng.random() < 0.6:
                        return False

        direct_count = self.direct_interaction_count.get(opponent, 0)
        if direct_count >= 3:
            direct_coop = self.direct_coop_count.get(opponent, 0)
            direct_rate = direct_coop / direct_count
            if direct_rate < 0.3:
                threshold = max(threshold, 0.65)
            elif direct_rate > 0.7:
                threshold = min(threshold, 0.25)
        if opp_rep < threshold:
            return False
        return True

