import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.total_count = {}
        self.my_history = []
        self.rounds_played = 0
        self.default_rep = 0.5
        self.my_coop_count = 0
        self.my_total_count = 0
        self.opponent_history = {}
        self.my_recent_actions = []
        self.last_interaction_round = {}
        self.exploited_recently = 0
        self.opp_coop_streak = {}
        self.opp_defect_streak = {}
        self.opp_def_after_coop = {}
        self.rep_change = {}
        self.opp_coop_rate = {}
        self.opp_total_obs = {}
        self.opp_coop_obs = {}
        self.others_coop_with_me = 0
        self.others_total_with_me = 0
        self.opp_behavior_consistency = {}
        self.opp_last_action = {}
        self.opp_last_action_before_my_turn = {}
        self.recent_opp_coop_with_me = {}
        self.self_reputation_estimate = 0.5
        self.my_recent_actions_list = []
        self.opp_volatility = {}
        self.reciprocal_coop_count = {}
        self.reciprocal_def_count = {}
        self.recent_opp_coop_rate = {}
        self.last_opponent_interaction = {}
        self.exploited_by = {}
        self.opp_coop_with_others = {}
        self.opp_total_with_others = {}
        # New: Track opponent's cooperation with me more heavily
        self.opp_coop_with_me_total = {}

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, self.default_rep)
        my_rep = self.reputation.get(self.agent_id, self.default_rep)
        opp_history = self.opponent_history.get(opponent, [])
        if len(opp_history) >= 3:
            recent_coop = sum(1 for a in opp_history[-3:] if a == 'cooperate') / 3
            if recent_coop == 1.0:
                opp_rep = min(1.0, opp_rep + 0.2)
            elif recent_coop <= 0.33:
                opp_rep = max(0.0, opp_rep - 0.2)
        threshold = 0.4
        if my_rep < 0.2:
            return False
        if self.exploited_recently >= 5:
            threshold = 0.5
        trend = self.rep_change.get(opponent, 0)
        if trend < -0.1:
            threshold = 0.6
        elif trend > 0.1:
            threshold = 0.35
        opp_rate = self.opp_coop_rate.get(opponent, 0.5)
        if opp_rate < 0.3:
            threshold = max(threshold, 0.55)
        elif opp_rate > 0.7:
            threshold = min(threshold, 0.3)
        opp_total = self.opp_total_obs.get(opponent, 0)
        opp_coop = self.opp_coop_obs.get(opponent, 0)
        if opp_total >= 10:
            observed_rate = opp_coop / opp_total
            if observed_rate < 0.25:
                threshold = max(threshold, 0.6)
            elif observed_rate > 0.75:
                threshold = min(threshold, 0.35)
        if self.others_total_with_me >= 5:
            others_rate = self.others_coop_with_me / self.others_total_with_me
            my_rate = self.my_coop_count / max(1, self.my_total_count)
            if others_rate < my_rate - 0.2:
                threshold = max(threshold, 0.55)
        consistency = self.opp_behavior_consistency.get(opponent, 1.0)
        if consistency < 0.4:
            threshold = max(threshold, 0.5)
        last_action_before = self.opp_last_action_before_my_turn.get(opponent, None)
        if last_action_before == 'defect':
            threshold = max(threshold, 0.55)
        recent_coop_with_me = self.recent_opp_coop_with_me.get(opponent, [])
        if len(recent_coop_with_me) >= 3:
            recent_rate = sum(1 for a in recent_coop_with_me if a == 'cooperate') / len(recent_coop_with_me)
            if recent_rate < 0.3:
                threshold = max(threshold, 0.6)
            elif recent_rate > 0.7:
                threshold = min(threshold, 0.3)
        volatility = self.opp_volatility.get(opponent, 0.0)
        if volatility > 0.5:
            threshold = max(threshold, 0.55)
        elif volatility > 0.3:
            threshold = max(threshold, 0.45)
        last_interaction = self.last_opponent_interaction.get(opponent, -1)
        if self.rounds_played - last_interaction > 10:
            threshold = max(threshold, 0.5)
        exploited_count = self.exploited_by.get(opponent, 0)
        if exploited_count >= 3:
            threshold = max(threshold, 0.6)
        opp_total_others = self.opp_total_with_others.get(opponent, 0)
        opp_coop_others = self.opp_coop_with_others.get(opponent, 0)
        if opp_total_others >= 5:
            third_party_rate = opp_coop_others / opp_total_others
            if third_party_rate < 0.3:
                threshold = max(threshold, 0.5)
            elif third_party_rate > 0.7:
                threshold = min(threshold, 0.35)
        # New: Stronger reaction to opponent's cooperation with me specifically
        coop_with_me_total = self.opp_coop_with_me_total.get(opponent, 0)
        if coop_with_me_total >= 3:
            coop_with_me_rate = coop_with_me_total / max(1, len(self.recent_opp_coop_with_me.get(opponent, [])))
            if coop_with_me_rate < 0.3:
                threshold = max(threshold, 0.7)
        if opp_rep < threshold:
            return False
        seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
        rng = random.Random(seed)
        my_coop_rate = self.my_coop_count / max(1, self.my_total_count)
        if my_coop_rate > 0.8:
            if rng.random() < 0.15:
                return False
        recent_with_opp = [a for (_, oid, a) in self.my_history if oid == opponent][-2:]
        if len(recent_with_opp) == 2 and all(a == 'cooperate' for a in recent_with_opp):
            if rng.random() < 0.1:
                return False
        elif rng.random() < 0.05:
            return False
        my_opp_history = [a for (_, oid, a) in self.my_history if oid == opponent]
        if len(my_opp_history) >= 2 and all(a == 'defect' for a in my_opp_history[-2:]):
            return False

        last_round = self.last_interaction_round.get(opponent, -1)
        if self.rounds_played - last_round > 5:
            if rng.random() < 0.3:
                return False

        coop_streak = self.opp_coop_streak.get(opponent, 0)
        defect_streak = self.opp_defect_streak.get(opponent, 0)
        if coop_streak >= 3:
            if rng.random() < 0.02:
                return False
        elif defect_streak >= 2:
            if rng.random() < 0.4:
                return False
        def_after_coop = self.opp_def_after_coop.get(opponent, 0)
        if def_after_coop >= 2:
            if rng.random() < 0.5:
                return False
        reciprocal_coop = self.reciprocal_coop_count.get(opponent, 0)
        reciprocal_def = self.reciprocal_def_count.get(opponent, 0)
        if reciprocal_coop > 0 and reciprocal_def == 0:
            if rng.random() < 0.1:
                return False
        elif reciprocal_def > 0 and reciprocal_coop == 0:
            if rng.random() < 0.6:
                return False
        recent_rate = self.recent_opp_coop_rate.get(opponent, 0.5)
        if reciprocal_def > reciprocal_coop and recent_rate > 0.7:
            if rng.random() < 0.15:
                return False
        if exploited_count >= 5 and reciprocal_def > reciprocal_coop:
            if rng.random() < 0.7:
                return False
        if opp_total_others >= 10 and third_party_rate < 0.2:
            if rng.random() < 0.5:
                return False
        # New: Extra punishment when opponent defects against me often
        if coop_with_me_total >= 3 and coop_with_me_rate < 0.2:
            if rng.random() < 0.6:
                return False
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
            coop = self.coop_count.get(agent_id, 0)
            new_rep = coop / total
            self.reputation[agent_id] = old_rep * (1 - alpha) + new_rep * alpha
            if agent_id in self.rep_change:
                self.rep_change[agent_id] = self.rep_change[agent_id] * 0.9 + (self.reputation[agent_id] - old_rep) * 0.1
            else:
                self.rep_change[agent_id] = self.reputation[agent_id] - old_rep
            if agent_id != self.agent_id:
                if agent_id not in self.opp_coop_rate:
                    self.opp_coop_rate[agent_id] = 0.5
                total_obs = self.total_count[agent_id]
                coop_obs = self.coop_count[agent_id]
                self.opp_coop_rate[agent_id] = coop_obs / max(1, total_obs)
                self.opp_total_obs[agent_id] = self.opp_total_obs.get(agent_id, 0) + 1
                if action == 'cooperate':
                    self.opp_coop_obs[agent_id] = self.opp_coop_obs.get(agent_id, 0) + 1
                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    if (last == 'cooperate') != (action == 'cooperate'):
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 0.0
                    else:
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 1.0
                else:
                    self.opp_behavior_consistency[agent_id] = 1.0
                self.opp_last_action[agent_id] = action

                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    change = 1.0 if (last == 'cooperate') != (action == 'cooperate') else 0.0
                    self.opp_volatility[agent_id] = self.opp_volatility.get(agent_id, 0.0) * 0.9 + change * 0.1
                else:
                    self.opp_volatility[agent_id] = 0.0

        if donor_id == self.agent_id and recipient_action == 'defect':
            self.exploited_recently += 1
        if self.rounds_played % 10 == 0 and self.exploited_recently > 0:
            self.exploited_recently -= 1

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_action)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = []
            self.opponent_history[recipient_id].append(recipient_action)
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                self.opp_total_with_others[agent_id] = self.opp_total_with_others.get(agent_id, 0) + 1
                if action == 'cooperate':
                    self.opp_coop_with_others[agent_id] = self.opp_coop_with_others.get(agent_id, 0) + 1

        if donor_id == self.agent_id:
            self.my_history.append((self.rounds_played, recipient_id, donor_action))
            self.rounds_played += 1
            self.my_total_count += 1
            if donor_action == 'cooperate':
                self.my_coop_count += 1
            self.my_recent_actions.append((recipient_id, donor_action))
            self.last_interaction_round[recipient_id] = self.rounds_played
            self.last_opponent_interaction[recipient_id] = self.rounds_played
            if donor_action == 'cooperate' and recipient_action == 'defect':
                self.opp_def_after_coop[recipient_id] = self.opp_def_after_coop.get(recipient_id, 0) + 1
            else:
                if donor_action != 'cooperate' or recipient_action != 'defect':
                    self.opp_def_after_coop[recipient_id] = 0
        elif recipient_id == self.agent_id:
            self.my_history.append((self.rounds_played, donor_id, recipient_action))
            self.rounds_played += 1
            self.my_total_count += 1
            if recipient_action == 'cooperate':
                self.my_coop_count += 1
            self.my_recent_actions.append((donor_id, recipient_action))
            self.last_interaction_round[donor_id] = self.rounds_played
            self.last_opponent_interaction[donor_id] = self.rounds_played
            if recipient_action == 'cooperate' and donor_action == 'defect':
                self.opp_def_after_coop[donor_id] = self.opp_def_after_coop.get(donor_id, 0) + 1
            else:
                if recipient_action != 'cooperate' or donor_action != 'defect':
                    self.opp_def_after_coop[donor_id] = 0
            self.others_total_with_me += 1
            if recipient_action == 'cooperate':
                self.others_coop_with_me += 1
            if donor_id not in self.recent_opp_coop_with_me:
                self.recent_opp_coop_with_me[donor_id] = []
            self.recent_opp_coop_with_me[donor_id].append(donor_action)
            if len(self.recent_opp_coop_with_me[donor_id]) > 5:
                self.recent_opp_coop_with_me[donor_id].pop(0)
            if donor_action == 'cooperate':
                self.reciprocal_coop_count[donor_id] = self.reciprocal_coop_count.get(donor_id, 0) + 1
            else:
                self.reciprocal_def_count[donor_id] = self.reciprocal_def_count.get(donor_id, 0) + 1
            if donor_id not in self.recent_opp_coop_rate:
