            long_total = self.long_term_total.get(agent_id, 0) + 1
            self.long_term_total[agent_id] = long_total
            long_new = (long_old * (long_total - 1) + (1.0 if action == 'cooperate' else 0.0)) / long_total
            self.long_term_reputation[agent_id] = long_new
            if agent_id != self.agent_id:
