        my_rep = self.reputation.get(self.agent_id, self.default_rep)
        opp_history = self.opponent_history.get(opponent, [])
        if len(opp_history) >= 3:
            recent_coop = sum(1 for a in opp_history[-3:] if a == 'cooperate') / 3
            if recent_coop == 1.0:
