            def_rate = opp_def_others / opp_total_def_others
            if def_rate > 0.7:
                threshold = max(threshold, 0.6)
            elif def_rate < 0.3:
                threshold = min(threshold, 0.35)
        # Mutation: Trust score adjustment
        trust = self.trust_scores.get(opponent, 0.5)
        if trust < 0.3:
            threshold = max(threshold, 0.6)
        elif trust > 0.7:
            threshold = min(threshold, 0.3)
        if opp_rep < threshold:
            return False
