            if rng.random() < 0.15:
                return False
        if exploited_count >= 5 and reciprocal_def > reciprocal_coop:
            if rng.random() < 0.7:
                return False
        if opp_total_others >= 10 and third_party_rate < 0.2:
            if rng.random() < 0.5:
                return False
        # Extra punishment when opponent defects against me often
        if coop_with_me_total >= 3 and coop_with_me_rate < 0.2:
            if rng.random() < 0.6:
                return False
        # If opponent defects against me more than cooperates but has decent reputation, be cautious
        if def_with_me_total > coop_with_me_total and coop_with_me_total >= 2:
            if rng.random() < 0.3:
                return False
        # If I've been cooperating with them and they defect, increase probability of defection
        if my_total_with_opp >= 3 and my_coop_with_opp > my_def_with_opp:
            if def_with_me_total > coop_with_me_total:
                if rng.random() < 0.5:
                    return False
        # New: Adaptive learning rate based on total interactions - if few interactions, be more forgiving
        if self.total_interactions < 10:
            if rng.random() < 0.1:
                return False
        # New: Recent cooperation rate with opponent - if they've been cooperative recently, cooperate more
        recent_opp_actions = self.recent_opp_coop_rate.get(opponent, None)
        if recent_opp_actions is not None and recent_opp_actions > 0.8:
            if rng.random() < 0.05:
                return False
        # New: If recent 10 coop rate is very high, cooperate more
        if recent10 is not None and recent10 > 0.85:
            if rng.random() < 0.05:
                return False
        # New: If recent 10 coop rate is very low, defect more often
        if recent10 is not None and recent10 < 0.15:
            if rng.random() < 0.2:
                return False
        # New: If opponent cooperated with me last time, cooperate with high probability
        if len(recent2_with_me) >= 1 and recent2_with_me[-1] == 'cooperate':
            if rng.random() < 0.05:
                return False
        # New: If opponent defected with me last time, defect more often
        if len(recent2_with_me) >= 1 and recent2_with_me[-1] == 'defect':
            if rng.random() < 0.3:
                return False
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
