                return False
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        if self.total_interactions < 20:
            alpha = 0.2
        elif self.total_interactions > 100:
            alpha = 0.05
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
            coop = self.coop_count.get(agent_id, 0)
            new_rep = coop / total
            self.reputation[agent_id] = old_rep * (1 - alpha) + new_rep * alpha
            if agent_id in self.rep_change:
                self.rep_change[agent_id] = self.rep_change[agent_id] * 0.9 + (self.reputation[agent_id] - old_rep) * 0.1
            else:
                self.rep_change[agent_id] = self.reputation[agent_id] - old_rep
            if agent_id != self.agent_id:
                if agent_id not in self.opp_coop_rate:
                    self.opp_coop_rate[agent_id] = 0.5
                total_obs = self.total_count[agent_id]
                coop_obs = self.coop_count[agent_id]
                self.opp_coop_rate[agent_id] = coop_obs / max(1, total_obs)
                self.opp_total_obs[agent_id] = self.opp_total_obs.get(agent_id, 0) + 1
                if action == 'cooperate':
                    self.opp_coop_obs[agent_id] = self.opp_coop_obs.get(agent_id, 0) + 1
                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    if (last == 'cooperate') != (action == 'cooperate'):
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 0.0
                    else:
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 1.0
                else:
                    self.opp_behavior_consistency[agent_id] = 1.0
                self.opp_last_action[agent_id] = action

                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    change = 1.0 if (last == 'cooperate') != (action == 'cooperate') else 0.0
                    self.opp_volatility[agent_id] = self.opp_volatility.get(agent_id, 0.0) * 0.9 + change * 0.1
                else:
                    self.opp_volatility[agent_id] = 0.0

        if donor_id == self.agent_id and recipient_action == 'defect':
            self.exploited_recently += 1
        if self.rounds_played % 10 == 0 and self.exploited_recently > 0:
            self.exploited_recently -= 1

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_action)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = []
            self.opponent_history[recipient_id].append(recipient_action)
            # Track third-party observations
            if donor_id not in self.opp_coop_with_others:
                self.opp_coop_with_others[donor_id] = 0
                self.opp_total_with_others[donor_id] = 0
            if recipient_id not in self.opp_coop_with_others:
                self.opp_coop_with_others[recipient_id] = 0
                self

