        self.trust_update_strength = 0.35  # Mutation: stronger trust updates
        self.default_trust = 0.55  # Mutation: higher initial trust
        # New mutation: memory of third-party cooperation patterns
        self.third_party_coop_rate = {}
        self.third_party_total_obs = {}

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, self.default_rep)
        my_rep = self.reputation.get(self.agent_id, self.default_rep)
