        my_total_with_opp = my_coop_with_opp + my_def_with_opp
        if my_total_with_opp >= 3 and my_coop_with_opp > my_def_with_opp:
            if def_with_me_total > coop_with_me_total:
                threshold = max(threshold, 0.6)
        recent10 = self.opp_recent10_coop_rate.get(opponent, None)
        if recent10 is not None:
            if recent10 < 0.2:
                threshold = max(threshold, 0.7)
            elif recent10 > 0.8:
                threshold = min(threshold, 0.3)
        # New: Check last 5 interactions with me - if mixed, be more cautious
        last5 = self.opp_last5_with_me.get(opponent, [])
        if len(last5) >= 3:
            last5_coop = sum(1 for a in last5 if a == 'cooperate') / len(last5)
            if 0.3 <= last5_coop <= 0.7:
                threshold = max(threshold, 0.5)
        if opp_rep < threshold:
            return False
        seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
        rng = random.Random(seed)
        my_coop_rate = self.my_coop_count / max(1, self.my_total_count)
        if my_coop_rate > 0.8:
            if rng.random() < 0.15:
                return False
        recent_with_opp = [a for (_, oid, a) in self.my_history if oid == opponent][-2:]
        if len(recent_with_opp) == 2 and all(a == 'cooperate' for a in recent_with_opp):
            if rng.random() < 0.1:
                return False
        elif rng.random() < 0.05:
            return False
        my_opp_history = [a for (_, oid, a) in self.my_history if oid == opponent]
        if len(my_opp_history) >= 2 and all(a == 'defect' for a in my_opp_history[-2:]):
            return False

        last_round = self.last_interaction_round.get(opponent, -1)
        if self.rounds_played - last_round > 5:
            if rng.random() < 0.3:
                return False

        coop_streak = self.opp_coop_streak.get(opponent, 0)
        defect_streak = self.opp_defect_streak.get(opponent, 0)
        if coop_streak >= 3:
            if rng.random() < 0.02:
                return False
        elif defect_streak >= 2:
            if rng.random() < 0.4:
                return False
        def_after_coop = self.opp_def_after_coop.get(opponent, 0)
        if def_after_coop >= 2:
            if rng.random() < 0.5:
                return False
        reciprocal_coop = self.reciprocal_coop_count.get(opponent, 0)
        reciprocal_def = self.reciprocal_def_count.get(opponent, 0)
        if reciprocal_coop > 0 and reciprocal_def == 0:
            if rng.random() < 0.1:
                return False
        elif reciprocal_def > 0 and reciprocal_coop == 0:
            if rng.random() < 0.6:
                return False
        recent_rate = self.recent_opp_coop_rate.get(opponent, 0.5)
        if reciprocal_def > reciprocal_coop and recent_rate > 0.7:
            if rng.random() < 0.15:
                return False
        if exploited_count >= 5 and reciprocal_def > reciprocal_coop:
            if rng.random() < 0.7:
                return False
        if opp_total_others >= 10 and third_party_rate < 0.2:
            if rng.random() < 0.5:
                return False
        if coop_with_me_total >= 3 and coop_with_me_rate < 0.2:
            if rng.random() < 0.6:
                return False
        if def_with_me_total > coop_with_me_total and coop_with_me_total >= 2:
            if rng.random() < 0.3:
                return False
        if my_total_with_opp >= 3 and my_coop_with_opp > my_def_with_opp:
            if def_with_me_total > coop_with_me_total:
                if rng.random() < 0.5:
                    return False
        if self.total_interactions < 10:
            if rng.random() < 0.1:
                return False
        recent_opp_actions = self.recent_opp_coop_rate.get(opponent, None)
        if recent_opp_actions is not None and recent_opp_actions > 0.8:
            if rng.random() < 0.05:
                return False
        if recent10 is not None and recent10 > 0.85:
            if rng.random() < 0.05:
                return False
        if recent10 is not None and recent10 < 0.15:
            if rng.random() < 0.2:
                return False
        # New: If last 5 with me are mixed, slightly increase defection probability
        if len(last5) >= 3 and 0.3 <= last5_coop <= 0.7:
            if rng.random() < 0.1:
                return False
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        if self.total_interactions < 20:
            alpha = 0.2
        elif self.total_interactions > 100:
            alpha = 0.05
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            total = self.total_count[agent_id]
            coop = self.coop_count.get(agent_id, 0)
            new_rep = coop / total
            self.reputation[agent_id] = old_rep * (1 - alpha) + new_rep * alpha
            if agent_id in self.rep_change:
                self.rep_change[agent_id] = self.rep_change[agent_id] * 0.9 + (self.reputation[agent_id] - old_rep) * 0.1
            else:
                self.rep_change[agent_id] = self.reputation[agent_id] - old_rep
            if agent_id != self.agent_id:
                if agent_id not in self.opp_coop_rate:
                    self.opp_coop_rate[agent_id] = 0.5
                total_obs = self.total_count[agent_id]
                coop_obs = self.coop_count[agent_id]
                self.opp_coop_rate[agent_id] = coop_obs / max(1, total_obs)
                self.opp_total_obs[agent_id] = self.opp_total_obs.get(agent_id, 0) + 1
                if action == 'cooperate':
                    self.opp_coop_obs[agent_id] = self.opp_coop_obs.get(agent_id, 0) + 1
                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    if (last == 'cooperate') != (action == 'cooperate'):
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 0.0
                    else:
                        self.opp_behavior_consistency[agent_id] = self.opp_behavior_consistency.get(agent_id, 1.0) * 0.9 + 1.0
                else:
                    self.opp_behavior_consistency[agent_id] = 1.0
                self.opp_last_action[agent_id] = action

                if agent_id in self.opp_last_action:
                    last = self.opp_last_action[agent_id]
                    change = 1.0 if (last == 'cooperate') != (action == 'cooperate') else 0.0
                    self.opp_volatility[agent_id] = self.opp_volatility.get(agent_id, 0.0) * 0.9 + change * 0.1
                else:
                    self.opp_volatility[agent_id] = 0.0

        if donor_id == self.agent_id and recipient_action == 'defect':
            self.exploited_recently += 1
        if self.rounds_played % 10 == 0 and self.exploited_recently > 0:
            self.exploited_recently -= 1

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_id not in self.opponent_history:
