        self.exploited_by = {}
        self.opp_coop_with_others = {}
        self.opp_total_with_others = {}
        self.opp_coop_with_me_total = {}
        self.opp_def_with_me_total = {}
        self.my_coop_with_opponent = {}
        self.my_def_with_opponent = {}
        self.total_interactions = 0
        self.opp_recent_coop_rate = {}
        self.opp_recent_coop_with_me = {}
        self.opp_recent_def_with_me = {}
        self.generosity = 1.0
        self.trust_penalty = 0.1  # New: additional penalty for untrustworthy behavior

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, self.default_rep)
        my_rep = self.reputation.get(self.agent_id, self.default_rep)
        opp_history = self.opponent_history.get(opponent, [])
        if len(opp_history) >= 3:
            recent_coop = sum(1 for a in opp_history[-3:] if a == 'cooperate') / 3
            if recent_coop == 1.0:
                opp_rep = min(1.0, opp_rep + 0.2)
            elif recent_coop <= 0.33:
                opp_rep = max(0.0, opp_rep - 0.2)
        threshold = 0.4
        if my_rep < 0.2:
            return False
        if self.exploited_recently >= 5:
            threshold = 0.5
        trend = self.rep_change.get(opponent, 0)
        if trend < -0.1:
            threshold = 0.6
        elif trend > 0.1:
            threshold = 0.35
        opp_rate = self.opp_coop_rate.get(opponent, 0.5)
        if opp_rate < 0.3:
            threshold = max(threshold, 0.55)
        elif opp_rate > 0.7:
            threshold = min(threshold, 0.3)
        opp_total = self.opp_total_obs.get(opponent, 0)
        opp_coop = self.opp_coop_obs.get(opponent, 0)
        if opp_total >= 10:
            observed_rate = opp_coop / opp_total
            if observed_rate < 0.25:
                threshold = max(threshold, 0.6)
            elif observed_rate > 0.75:
                threshold = min(threshold, 0.35)
        if self.others_total_with_me >= 5:
            others_rate = self.others_coop_with_me / self.others_total_with_me
            my_rate = self.my_coop_count / max(1, self.my_total_count)
            if others_rate < my_rate - 0.2:
                threshold = max(threshold, 0.55)
        consistency = self.opp_behavior_consistency.get(opponent, 1.0)
        if consistency < 0.4:
            threshold = max(threshold, 0.5)
        last_action_before = self.opp_last_action_before_my_turn.get(opponent, None)
        if last_action_before == 'defect':
            threshold = max(threshold, 0.55)
        recent_coop_with_me = self.opp_recent_coop_with_me.get(opponent, [])
        if len(recent_coop_with_me) >= 3:
            recent_rate = sum(1 for a in recent_coop_with_me if a == 'cooperate') / len(recent_coop_with_me)
            if recent_rate < 0.3:
                threshold = max(threshold, 0.6)
            elif recent_rate > 0.7:
                threshold = min(threshold, 0.3)
        volatility = self.opp_volatility.get(opponent, 0.0)
        if volatility > 0.5:
            threshold = max(threshold, 0.55)
        elif volatility > 0.3:
            threshold = max(threshold, 0.45)
        last_interaction = self.last_opponent_interaction.get(opponent, -1)
        if self.rounds_played - last_interaction > 10:
            threshold = max(threshold, 0.5)
        exploited_count = self.exploited_by.get(opponent, 0)
        if exploited_count >= 3:
            threshold = max(threshold, 0.6)
