        seed = self.rounds_played * 100 + opponent * 7 + self.agent_id
        rng = random.Random(seed)
        my_coop_rate = self.my_coop_count / max(1, self.my_total_count)
        if my_coop_rate > 0.8:
            if rng.random() < 0.15:
                return False
        recent_with_opp = [a for (_, oid, a) in self.my_history if oid == opponent][-2:]
        if len(recent_with_opp) == 2 and all(a == 'cooperate' for a in recent_with_opp):
            if rng.random() < 0.1:
                return False
        elif rng.random() < 0.05:
            return False
        my_opp_history = [a for (_, oid, a) in self.my_history if oid == opponent]
        if len(my_opp_history) >= 2 and all(a == 'defect' for a in my_opp_history[-2:]):
