            if opp_third_party_rate < my_third_party_rate - 0.4:
                if rng.random() < 0.6:
                    return False
        # Mutation: Trust-based occasional defection
        if trust < 0.4 and rng.random() < 0.2:
            return False
        if self.defection_count.get(opponent, 0) > 3 and rng.random() < 0.25:
            return False
        if trust_change < -0.2 and rng.random() < 0.3:
            return False
        coop_with = self.coop_with_agent.get(opponent, 0)
        total_with = self.total_with_agent.get(opponent, 0)
        if total_with >= 5 and coop_with / total_with > 0.8:
            if rng.random() < 0.1:
                return False
        # New mutation: If opponent has a high defection rate with me and we have interacted many times, defect more
        if total_with >= 3 and reciprocal_def > reciprocal_coop * 2 and rng.random() < 0.15:
            return False
        # New mutation: Increase cooperation with high trust and low tolerance
        if trust > 0.7 and tolerance < 0.3 and rng.random() < 0.1:
            return True
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
