        my_total_with_opp = my_coop_with_opp + my_def_with_opp
        if my_total_with_opp >= 3 and my_coop_with_opp > my_def_with_opp:
            if def_with_me_total > coop_with_me_total:
                threshold = max(threshold, 0.6)
        # New: if we have cooperated with opponent more than defected, and they have defected against us more than cooperated, punish
        if my_total_with_opp >= 3 and my_coop_with_opp > my_def_with_opp and def_with_me_total > coop_with_me_total:
            threshold = max(threshold, 0.7)
        # New: retaliate more strongly if opponent has defected against us frequently
        if def_with_me_total >= 5 and coop_with_me_total < def_with_me_total:
            threshold = max(threshold, 0.8)
        if opp_rep < threshold:
            return False
