                    self.opp_volatility[agent_id] = self.opp_volatility.get(agent_id, 0.0) * 0.9 + change * 0.1
                else:
                    self.opp_volatility[agent_id] = 0.0

        if donor_id == self.agent_id:
            if recipient_id not in self.opp_recent_coop_with_me:
                self.opp_recent_coop_with_me[recipient_id] = []
                self.opp_recent_def_with_me[recipient_id] = []
            if recipient_action == 'cooperate':
                self.opp_recent_coop_with_me[recipient_id].append(1)
                self.opp_recent_def_with_me[recipient_id].append(0)
            else:
                self.opp_recent_coop_with_me[recipient_id].append(0)
                self.opp_recent_def_with_me[recipient_id].append(1)
            if len(self.opp_recent_coop_with_me[recipient_id]) > 10:
                self.opp_recent_coop_with_me[recipient_id].pop(0)

