                return False
        # New: If opponent has cooperated with me in the last 3 interactions, increase chance of cooperation
        recent_interactions = self.recent_interactions.get(opponent, [])
        if len(recent_interactions) >= 3 and all(a == 'cooperate' for a in recent_interactions[-3:]):
            if rng.random() < 0.15:
                return True
        # New: If I have cooperated with this opponent more than they have with me, be slightly more cautious
        if my_coop_with_opp > coop_with_me_total and my_total_with_opp >= 3:
            if rng.random() < 0.1:
                return False
        # New: If opponent has exploited me more than 3 times, defect more often
        if self.exploitation_count.get(opponent, 0) > 3:
            if rng.random() < 0.6:
                return False
        # New: If opponent has cooperated with me recently, reward with higher cooperation probability
        if len(recent_coop_with_me) >= 2 and all(a == 'cooperate' for a in recent_coop_with_me[-2:]):
            if rng.random() < 0.05:
                return True
        # New: If opponent has a high reputation but hasn't interacted with me much, be slightly trusting
        if opp_rep > 0.8 and coop_with_me_total < 2:
            if rng.random() < 0.1:
                return True
        return True

