        if opp_total_others >= 10 and third_party_rate < 0.3 and coop_with_me_rate > 0.6:
            if rng.random() < self.third_party_forgiveness * 0.1:
                return False
        # New trust-based adjustment: if opponent has consistently cooperated with us, increase cooperation
        if coop_with_me_total >= 5 and coop_with_me_rate > 0.8 and self.trust_weight > 0.5:
            if rng.random() < 0.05 * self.trust_weight:
                return False
        # New: retaliate more strongly when opponent has defected many times against us
        if def_with_me_total >= 5 and coop_with_me_total < def_with_me_total:
            if rng.random() < self.retaliation_factor * 0.4:
                return False
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        alpha = 0.1
        if self.total_interactions < 20:
            alpha = 0.2
        elif self.total_interactions > 100:
            alpha = 0.05
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            old_rep = self.reputation.get(agent_id, self.default_rep)
            self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
